/// The roots: the value's top carrying the run. Every other linear tag consumes.
pub const fn producer(t: Tag) -> bool { matches!(t, Tag::RLf | Tag::RLb | Tag::RSf | Tag::RSb | Tag::RFf | Tag::RFb) }

/// Agents carrying a run (compile.ts `CURSOR`): roots, heads, readers, tris reading, a map turned round.
pub const fn runs(t: Tag) -> bool { matches!(t, Tag::RLf | Tag::RLb | Tag::RSf | Tag::RSb | Tag::RFf | Tag::RFb | Tag::Hf | Tag::Kuf | Tag::Kcf | Tag::Kssf | Tag::Ksff | Tag::Hb | Tag::Kub | Tag::Kcb | Tag::Kssb | Tag::Ksfb | Tag::TLrf | Tag::TLrfp | Tag::TLrb | Tag::TLrbp | Tag::TSrf | Tag::TSrfp | Tag::TSrb | Tag::TSrbp | Tag::TFrf | Tag::TFrfp | Tag::TFrb | Tag::TFrbp | Tag::TFcf | Tag::TFcfp | Tag::TFcb | Tag::TFcbp | Tag::PHRf | Tag::PHRb) }

